text:
{
  "jobs": [
    {
      "text": "Использовать мобильный интернет в зарубежных поездках для карт, навигации и мессенджеров",
      "quote": "Звонки я вообще не делаю — только мессенджеры, так что мне чисто интернет нужен."
    },
    {
      "text": "Находить и покупать дешёвые eSIM для поездок",
      "quote": "Пару раз брала eSIM в Telegram-каналах, там цены смешные — рублей 200-300, и норм работает"
    },
    {
      "text": "Сравнивать цены на интернет в поездках перед покупкой",
      "quote": "Обычно я просто гуглю «интернет в Грузии цена» и смотрю, сколько стоят местные операторы — в Грузии, например, можно за 10 лари взять норм пакет. А потом сравниваю с eSIM-вариантами"
    },
    {
      "text": "Перепроверять надёжность продавца eSIM по отзывам и обзорам",
      "quote": "Ну, сначала я лезу в поисковик и смотрю, что пишут на vc.ru и в телеграм-каналах типа «eSIM для туристов». Потом открываю YouTube и гляжу пару обзоров, где люди прямо на камеру тестируют"
    },
    {
      "text": "Покупать eSIM заранее, до вылета, и активировать по прибытии",
      "quote": "Обычно я покупаю eSIM за пару дней до вылета, пока сижу [АДРЕС]и копаюсь в телефоне. Установил инструкцию из канала — там ссылка на QR-код, скачиваешь, активируешь, и всё. А на месте я уже включаю её, когда прилетаю"
    },
    {
      "text": "Использовать Wi-Fi в отелях и кафе для экономии",
      "quote": "В основном сижу на вайфае в отелях и кафешках, потому что покупать симки у операторов как-то дороговато."
    },
    {
      "text": "Платить за то, что экономит время и нервы в критический момент",
      "quote": "Охотнее всего плачу за то, что экономит время и нервы — например, за нормальный интернет, если я потерялась и надо найти дорогу."
    }
  ],
  "pains": [
    {
      "text": "Высокая цена туристических тарифов у операторов",
      "quote": "А ещё меня дико бесит платить 1000+ рублей операторам за «туристические» тарифы, которые всё равно работают через раз."
    },
    {
      "text": "Недоверие к продавцам eSIM в Telegram и страх мошенничества",
      "quote": "Неудобно, что приходится доверять непонятным людям в Telegram — ты же не знаешь, кто там сидит, может, завтра канал заблокируют, и всё, привет."
    },
    {
      "text": "Отсутствие поддержки у продавцов eSIM в Telegram",
      "quote": "Ещё бесит, что у таких каналов нет поддержки: если что-то не работает, ты просто остаёшься один на один с проблемой."
    },
    {
      "text": "Тревога в первый час после прилёта из-за риска остаться без связи",
      "quote": "Ну, блин, страшно же, что оплата не прошла, или симка не активировалась, и я останусь без карт и навигации в незнакомом городе."
    },
    {
      "text": "Скрытые условия по сроку действия пакетов",
      "quote": "Ещё меня бесит, что у операторов вечно какие-то скрытые условия: например, «пакет действует 7 дней», а ты летишь на 10 — и доплачивай."
    },
    {
      "text": "Ограниченная работа карты МИР за границей",
      "quote": "Плюс я картой МИР оплачивала, а она не везде работает, так что если eSIM глюканет, придётся искать вайфай и паниковать."
    },
    {
      "text": "Недоверие к рекламе и заказным обзорам",
      "quote": "Там часто сравнивают цены и сервисы, но я всё равно не доверяю рекламе — сразу вижу, когда текст заказной."
    },
    {
      "text": "Сомнения в подлинности отзывов",
      "quote": "Я пролистала отзывы в том же канале — там какие-то люди писали «спасибо, всё работает», но это же может быть накрутка, я понимаю."
    },
    {
      "text": "Ощущение лотереи при выборе eSIM",
      "quote": "В общем, это как игра в рулетку — пока везёт, но нервы тратишь."
    }
  ],
  "current_solutions": [
    {
      "text": "Покупка eSIM в Telegram-каналах",
      "quote": "Пару раз брала eSIM в Telegram-каналах, там цены смешные — рублей 200-300, и норм работает"
    },
    {
      "text": "Использование Wi-Fi в отелях и кафе",
      "quote": "В основном сижу на вайфае в отелях и кафешках"
    },
    {
      "text": "Покупка местной симки в аэропорту",
      "quote": "то ли снова рискнуть с каналом, то ли взять нормальную симку в аэропорту, но там ценник конский"
    },
    {
      "text": "Покупка местной симки у местных операторов",
      "quote": "в Грузии, например, можно за 10 лари взять норм пакет"
    },
    {
      "text": "Использование сервисов вроде Airalo",
      "quote": "Там какой-то сервис типа Airalo или что-то подобное рекламировали, но я полезла в тот же Telegram-канал, потому что там было 300 рублей против 600."
    },
    {
      "text": "Поиск информации на vc.ru, в блогах, на YouTube, Pikabu, Reddit",
      "quote": "Обычно я просто забиваю в поиск «лучшие eSIM для поездок» и читаю статьи на vc.ru или в каких-нибудь блогах про путешествия."
    },
    {
      "text": "Советы знакомых, которые пользовались сервисом",
      "quote": "Ещё спрашиваю у знакомых, кто часто ездит: подруга, например, посоветовала тот Telegram-канал, и я поверила, потому что она реально им пользовалась, а не за спасибо рекламирует."
    }
  ],
  "barriers": [
    {
      "text": "Барьер выбора: недоверие к продавцам eSIM в Telegram из-за риска мошенничества",
      "quote": "Неудобно, что приходится доверять непонятным людям в Telegram — ты же не знаешь, кто там сидит, может, завтра канал заблокируют, и всё, привет."
    },
    {
      "text": "Барьер выбора: сомнения в подлинности отзывов и обзоров",
      "quote": "Я пролистала отзывы в том же канале — там какие-то люди писали «спасибо, всё работает», но это же может быть накрутка, я понимаю."
    },
    {
      "text": "Барьер оплаты: ограниченная работа карты МИР за границей",
      "quote": "Плюс я картой МИР оплачивала, а она не везде работает, так что если eSIM глюканет, придётся искать вайфай и паниковать."
    },
    {
      "text": "Барьер понимания: непрозрачные условия у операторов (срок действия, роуминг)",
      "quote": "Ещё непонятно, будет ли этот пакет работать в Грузии и Казахстане без доплат, или они напишут мелким шрифтом «роуминг» и сдерут ещё."
    },
    {
      "text": "Барьер выбора: недоверие к операторам из-за скрытых условий",
      "quote": "Ещё меня бесит, что у операторов вечно какие-то скрытые условия: например, «пакет действует 7 дней», а ты летишь на 10 — и доплачивай."
    },
    {
      "text": "Барьер выбора: недоверие к качеству связи у операторов в роуминге",
      "quote": "Второе — я не верю, что у них там всё гладко работает: вдруг в роуминге скорость режут или он вообще не ловит, а поддержка скажет «ну вы же в другой стране, норм»."
    },
    {
      "text": "Барьер оплаты: цена выше 500 рублей за пакет",
      "quote": "Я бы полезла сравнивать с тем, что есть на рынке, и если у них выйдет дороже 500 рублей, то смысла нет — я лучше рискну с каким-нибудь каналом."
    }
  ],
  "triggers": [
    {
      "text": "Совет подруги, которая уже пользовалась сервисом",
      "quote": "Ну, подруга посоветовала — она тоже вечно ищет, где подешевле, и сказала, что брала там пару раз, всё ок."
    },
    {
      "text": "Низкая цена по сравнению с альтернативами",
      "quote": "Я подумала: «Ну, 250 рублей — не такая уж большая сумма, если кинут, не умру»."
    },
    {
      "text": "Раздражение от дорогих тарифов операторов",
      "quote": "А ещё меня дико бесит платить 1000+ рублей операторам за «туристические» тарифы, которые всё равно работают через раз."
    },
    {
      "text": "Необходимость срочно найти дорогу, когда потерялась",
      "quote": "Я забила на экономию, включила мобильные данные на той eSIM, которая оставалась, и за 2 минуты нашла дорогу к набережной."
    },
    {
      "text": "Окончание срока действия eSIM в поездке",
      "quote": "через 7 дней она просто отключилась, хотя трафик остался. Я тогда сидела в кафе в Тбилиси и материлась, потому что надо было найти новый вариант."
    }
  ],
  "words": [
    "смешные цены",
    "страшновато",
    "кинут",
